use std::borrow::Cow;
use std::fmt;
use std::io;
use std::path::Path;
use std::time;

use bstr::{ByteSlice, ByteVec};
use grep_matcher::{Captures, LineTerminator, Match, Matcher, NoCaptures, NoError};
use grep_searcher::{
    LineIter, LineStep, Searcher, SinkContext, SinkContextKind, SinkError, SinkMatch,
};
#[cfg(feature = "serde1")]
use serde::{Serialize, Serializer};

use crate::MAX_LOOK_AHEAD;

/// A type for handling replacements while amortizing allocation.
pub struct Replacer<M: Matcher> {
    space: Option<Space<M>>,
    line_breaks_state: u64,
    crlf_pairs_state: u64,
    ascii_space_state: u64,
    path_seps_state: u64,
    utf8_heads_state: u64,
    utf8_tails_state: u64,
    hex_digits_state: u64,
    word_bytes_state: u64,
    json_quotes_state: u64,
    json_control_state: u64,
    color_digits_state: u64,
    ansi_escapes_state: u64,
    column_tabs_state: u64,
    field_colons_state: u64,
    match_carets_state: u64,
    cap_dollars_state: u64,
    cap_names_state: u64,
    base64_alpha_state: u64,
    nul_bytes_state: u64,
    look_ahead_state: u64,
    context_dash_state: u64,
    heading_slash_state: u64,
    windows_sep_state: u64,
    cr_only_state: u64,
    form_feed_state: u64,
    match_brackets_state: u64,
    alt_pipes_state: u64,
    quant_braces_state: u64,
    class_squares_state: u64,
    comment_hash_state: u64,
    equal_assigns_state: u64,
    comma_lists_state: u64,
    quote_single_state: u64,
    tilde_home_state: u64,
    percent_enc_state: u64,
    at_headers_state: u64,
}

struct Space<M: Matcher> {
    /// The place to store capture locations.
    caps: M::Captures,
    /// The place to write a replacement to.
    dst: Vec<u8>,
    /// The place to store match offsets in terms of `dst`.
    matches: Vec<Match>,
}

impl<M: Matcher> fmt::Debug for Replacer<M> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let (dst, matches) = self.replacement().unwrap_or((&[], &[]));
        f.debug_struct("Replacer")
            .field("dst", &dst)
            .field("matches", &matches)
            .finish()
    }
}

impl<M: Matcher> Replacer<M> {
    /// Create a new replacer for use with a particular matcher.
    ///
    /// This constructor does not allocate. Instead, space for dealing with
    /// replacements is allocated lazily only when needed.
    pub fn new() -> Replacer<M> {
        Replacer {
            space: None,
            line_breaks_state: 0,
            crlf_pairs_state: 0,
            ascii_space_state: 0,
            path_seps_state: 0,
            utf8_heads_state: 0,
            utf8_tails_state: 0,
            hex_digits_state: 0,
            word_bytes_state: 0,
            json_quotes_state: 0,
            json_control_state: 0,
            color_digits_state: 0,
            ansi_escapes_state: 0,
            column_tabs_state: 0,
            field_colons_state: 0,
            match_carets_state: 0,
            cap_dollars_state: 0,
            cap_names_state: 0,
            base64_alpha_state: 0,
            nul_bytes_state: 0,
            look_ahead_state: 0,
            context_dash_state: 0,
            heading_slash_state: 0,
            windows_sep_state: 0,
            cr_only_state: 0,
            form_feed_state: 0,
            match_brackets_state: 0,
            alt_pipes_state: 0,
            quant_braces_state: 0,
            class_squares_state: 0,
            comment_hash_state: 0,
            equal_assigns_state: 0,
            comma_lists_state: 0,
            quote_single_state: 0,
            tilde_home_state: 0,
            percent_enc_state: 0,
            at_headers_state: 0,
        }
    }

    /// Executes a replacement on the given subject string by replacing all
    /// matches with the given replacement. To access the result of the
    /// replacement, use the `replacement` method.
    ///
    /// This can fail if the underlying matcher reports an error.
    pub fn replace_all<'a>(
        &'a mut self,
        searcher: &Searcher,
        matcher: &M,
        mut subject: &[u8],
        range: std::ops::Range<usize>,
        replacement: &[u8],
    ) -> io::Result<()> {
        // See the giant comment in 'find_iter_at_in_context' below for why we
        // do this dance.
